    <>
      <Button onClick={() => setOpen(true)}>Empezar</Button>
      <Tour
        open={open}
        onOpenChange={setOpen}
        labels={{
          skip: 'Omitir',
          back: 'Atrás',
          next: 'Siguiente',
          done: 'Listo',
          close: 'Cerrar',
          progress: (step, total) => `Paso ${step} de ${total}`,
